func TestReadBatchRenameMappingJSON(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	path := filepath.Join(dir, "mapping.json")
	if err := os.WriteFile(path, []byte(`{"abc":"Title"," empty ":"  Trimmed  "}`), 0o600); err != nil {
		t.Fatal(err)
	}
	got, err := readBatchRenameMapping(path)
	if err != nil {
		t.Fatal(err)
	}
	if got["abc"] != "Title" {
		t.Fatalf("abc = %q, want Title", got["abc"])
	}
	if got["empty"] != "Trimmed" {
		t.Fatalf("empty = %q, want Trimmed", got["empty"])
	}
}

